(1525505, 201666, 37252, '<td valign="top">would have liked the skin tones to be more evident - but love the photo</td>', 'would have liked the skin tones to be more evident - but love the photo', '2005-07-11 04:33:25.000000', NULL, 1),
(1525506, 200311, 93, '<td valign="top">Gorgeous close up.. look at those lashes!  Not the strongest on the "family" theme, for my tastes, but a beautiful capture.</td>', 'Gorgeous close up.. look at those lashes!  Not the strongest on the "family" theme, for my tastes, but a beautiful capture.', '2005-07-11 04:33:31.000000', NULL, 1),
