INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1526768, 202444, 34659, '<td valign="top">Great DOF and composition!  Love the expression too.  At first, I thought the shot was too bright, but upon further examination I think it works - brings out the innocence, purity, and frailty of the child''s expression.  Really nice job.</td>', 'Great DOF and composition!  Love the expression too.  At first, I thought the shot was too bright, but upon further examination I think it works - brings out the innocence, purity, and frailty of the child''s expression.  Really nice job.', '2005-07-11 13:30:13.000000', NULL, 1),
(1526769, 202220, 24314, '<td valign="top">the main thing I like about this is the duck at the right hand side. He''s either coming in to land or just flapping his wings, but I like the fact that he''s level with the boat on the other side... does that make sense? lol</td>', 'the main thing I like about this is the duck at the right hand side. He''s either coming in to land or just flapping his wings, but I like the fact that he''s level with the boat on the other side... does that make sense? lol', '2005-07-11 13:30:15.000000', NULL, 1),
(1526771, 202177, 24314, '<td valign="top">I instantly went awwww when I saw this. such a nice warm feeling and a lovely shot.</td>', 'I instantly went awwww when I saw this. such a nice warm feeling and a lovely shot.', '2005-07-11 13:30:39.000000', NULL, 1),
(1526772, 202298, 34659, '<td valign="top">Great shot and DOF!  Love the crop showing the height of the rock face (including all the bird poop - lol).  The white on the gulls'' heads is a little bright and the shadows in the rocks is a little dark (IMHO), but otherwise it''s difficult to find anything else negative about it.  Very nice job!  10</td>', 'Great shot and DOF!  Love the crop showing the height of the rock face (including all the bird poop - lol).  The white on the gulls'' heads is a little bright and the shadows in the rocks is a little dark (IMHO), but otherwise it''s difficult to find anything else negative about it.  Very nice job!  10', '2005-07-11 13:31:06.000000', NULL, 1),
