INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1530427, 202007, 24454, '<td valign="top">Awwwww. . . .and he has a boo-boo on his leg!!!   I love these kinds of dogs.  They are so sweet and loyal.   They say "family" everytime you look in their eyes, right???  :)</td>', 'Awwwww. . . .and he has a boo-boo on his leg!!!   I love these kinds of dogs.  They are so sweet and loyal.   They say "family" everytime you look in their eyes, right???  :)', '2005-07-12 16:48:40.000000', NULL, 1),
(1530428, 202073, 39531, '<td valign="top">I think it is composed very well ... seems the light is a bit week on the left and not overall well balanced ... nice faces and you did get the "spark of life" in the eyes :)</td>', 'I think it is composed very well ... seems the light is a bit week on the left and not overall well balanced ... nice faces and you did get the "spark of life" in the eyes :)', '2005-07-12 16:48:40.000000', NULL, 1),
