(1530487, 200542, 39531, '<td valign="top">well posed and shot ... excellent exposure ... love the saturation and use of lines.</td>', 'well posed and shot ... excellent exposure ... love the saturation and use of lines.', '2005-07-12 17:03:59.000000', NULL, 1),
(1530491, 202469, 39531, '<td valign="top">hmmmm maybe the overexposed brightness is what you wanted but, I think it washes the shot out too much.</td>', 'hmmmm maybe the overexposed brightness is what you wanted but, I think it washes the shot out too much.', '2005-07-12 17:04:39.000000', NULL, 1),
