(1530500, 202304, 39531, '<td valign="top">what a lovely shot ...</td>', 'what a lovely shot ...', '2005-07-12 17:07:45.000000', NULL, 1),
(1530501, 202391, 39531, '<td valign="top">awesome exposure , great balance and color</td>', 'awesome exposure , great balance and color', '2005-07-12 17:08:17.000000', NULL, 1),
(1530503, 202399, 39531, '<td valign="top">great use of light</td>', 'great use of light', '2005-07-12 17:08:33.000000', NULL, 1),
