(1540684, 201690, 37851, '<td valign="top">This looks very staged.</td>', 'This looks very staged.', '2005-07-17 10:11:27.000000', NULL, 1),
(1540686, 201854, 37851, '<td valign="top">Is he going to bite?</td>', 'Is he going to bite?', '2005-07-17 10:11:58.000000', NULL, 1),
(1540688, 202169, 37851, '<td valign="top">I am not sure I see "family" here, but I really like quality.</td>', 'I am not sure I see "family" here, but I really like quality.', '2005-07-17 10:13:12.000000', NULL, 1),
(1540719, 201823, 164, '<td valign="top">Lighting is too harsh</td>', 'Lighting is too harsh', '2005-07-17 10:29:51.000000', NULL, 1),
